#!/usr/bin/env python3
"""Emit one ordered process-global registry pack list for a final target."""

import argparse
from pathlib import Path


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("output", type=Path)
    parser.add_argument("packs", nargs="+", metavar="SYMBOL")
    args = parser.parse_args()

    if len(set(args.packs)) != len(args.packs):
        raise SystemExit("compose_registry: duplicate pack symbol")

    lines = [
        "/* generated by compose_registry.py, do not edit. */",
        "",
        '#include "core/registry.h"',
        "",
    ]
    for symbol in args.packs:
        lines.append(f"extern const registry_pack {symbol};")
    lines.extend(
        [
            "",
            "const registry_pack *const REGISTRY_PACKS[] = {",
        ]
    )
    lines.extend(f"    &{symbol}," for symbol in args.packs)
    lines.extend(
        [
            "};",
            f"const int REGISTRY_PACK_COUNT = {len(args.packs)};",
            "",
        ]
    )
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text("\n".join(lines), encoding="utf-8")


if __name__ == "__main__":
    main()
